// AddOrderHandler.tsx
import React, { useCallback, useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { IProductCatRes, IProductItemRes } from 'ApiFarm/interface/product';
import { fetchProductCategory, fetchProductItem } from 'ApiFarm/product';
import { AxiosError } from 'axios';
import MenuAddListHandlerArea from 'ComponentsFarm/element/AddOrder/MenuAddListHandlerArea';
import MenuSelectArea from 'ComponentsFarm/element/AddOrder/MenuSelectArea';
import { ReceiptHandlerPopWrap } from 'ComponentsFarm/styles/common';
import useSelectModal from 'HookFarm/useSelectModal';
import { observer } from 'mobx-react';
import { orderStore } from 'MobxFarm/store';
import { AddOrderContent, MenuSelectAreaWrap } from './popStyle';

const AddOrderHandler = () => {
  const { hideModal } = useSelectModal();
  const [selectedCategory, setSelectedCategory] = useState<number | null>(1);
  const [selectedMenu, setSelectedMenu] = useState<number | null>(null);
  const [selectedOptions, setSelectedOptions] = useState<number[]>([]);
  const [editingMenuIdx, setEditingMenuIdx] = useState<number | null>(null);

  const onClose = useCallback(() => {
    orderStore.reset();
    hideModal('pop');
  }, [hideModal]);

  const { data: categoryData } = useQuery<
    { list: IProductCatRes[] },
    AxiosError
  >(['productCategory'], () => fetchProductCategory());

  const { data: itemData } = useQuery<{ list: IProductItemRes[] }, AxiosError>(
    ['productItem', selectedCategory],
    () =>
      fetchProductItem({
        search_product_class: selectedCategory,
      }),
    {
      enabled: selectedCategory !== null,
    }
  );

  const handleMenuSelect = (productIdx: number) => {
    setEditingMenuIdx(null);
    setSelectedMenu(productIdx);
    setSelectedOptions([]);
  };

  const handleMenuDeselect = useCallback((type: string, optionIdx?: number) => {
    if (type === 'menu') {
      setSelectedMenu(null);
      setSelectedOptions([]);
    } else if (type === 'option') {
      setSelectedOptions(prevSelectedOptions =>
        prevSelectedOptions.filter(option => option !== optionIdx)
      );
    }
  }, []);

  const handleOptionSelect = (optionIdx: number) => {
    const optionIndex = selectedOptions.indexOf(optionIdx);
    if (optionIndex === -1) {
      setSelectedOptions([...selectedOptions, optionIdx]);
    } else {
      setSelectedOptions(
        selectedOptions.filter(option => option !== optionIdx)
      );
    }
  };

  const handleEditMenu = (menuId: number) => {
    const menuToEdit = orderStore.menus.find(menu => menu.id === menuId);
    if (menuToEdit) {
      setEditingMenuIdx(menuId);
      setSelectedCategory(menuToEdit.category_idx);
      setSelectedMenu(menuToEdit.product_idx);
      setSelectedOptions(
        menuToEdit.selected_options.map(option => option.option_idx)
      );
    }
  };

  const handleAddToOrder = () => {
    if (selectedMenu !== null) {
      const selectedMenuData = itemData?.list.find(
        item => item.product_idx === selectedMenu
      );
      if (selectedMenuData) {
        if (editingMenuIdx !== null) {
          const existingMenu = orderStore.menus.find(
            menu => menu.id === editingMenuIdx
          );
          const updatedOptions = selectedOptions.map(optionIdx => {
            const optionData = selectedMenuData.set_option_list.find(
              option => option.product_idx === optionIdx
            );
            const existingOption = existingMenu?.selected_options.find(
              option => option.option_idx === optionData?.product_idx
            );
            return {
              option_idx: optionData?.product_idx || 0,
              option_name: optionData?.product_name || '',
              quantity: existingOption?.quantity || 1,
            };
          });
          orderStore.updateMenuOptions(Number(editingMenuIdx), updatedOptions);
          setEditingMenuIdx(null);
        } else {
          orderStore.addMenu({
            product_idx: selectedMenuData.product_idx,
            product_name: selectedMenuData.product_name,
            category_idx: selectedCategory!,
            quantity: 1,
            selected_options: selectedOptions.map(optionIdx => {
              const optionData = selectedMenuData.set_option_list.find(
                option => option.product_idx === optionIdx
              );
              return {
                option_idx: optionData?.product_idx || 0,
                option_name: optionData?.product_name || '',
                quantity: 1,
              };
            }),
          });
        }
      }
    }
    setSelectedMenu(null);
    setSelectedOptions([]);
    setEditingMenuIdx(null);
  };

  return (
    <ReceiptHandlerPopWrap>
      <h2>
        <span className="txt_receipt_name">주문 추가</span>
        <button type="button" className="btn_go_prev" onClick={onClose}>
          이전화면 이동하기
        </button>
      </h2>
      <AddOrderContent>
        <MenuSelectAreaWrap>
          <ul className="list_category">
            {categoryData?.list.map(category => (
              <li key={category.product_class_idx}>
                <button
                  type="button"
                  className={
                    selectedCategory === category.product_class_idx ? 'on' : ''
                  }
                  onClick={() => {
                    setSelectedCategory(category.product_class_idx);
                    setSelectedMenu(null);
                    setSelectedOptions([]);
                    setEditingMenuIdx(null);
                  }}
                >
                  {category.class_name}
                </button>
              </li>
            ))}
          </ul>
          <MenuSelectArea
            itemData={itemData}
            selectedCategory={selectedCategory}
            selectedMenu={selectedMenu}
            selectedOptions={selectedOptions}
            onMenuSelect={handleMenuSelect}
            onOptionSelect={handleOptionSelect}
            onAddToOrder={handleAddToOrder}
          />
        </MenuSelectAreaWrap>
        <MenuAddListHandlerArea
          hideModal={hideModal}
          onEditMenu={handleEditMenu}
          onMenuDeselect={handleMenuDeselect}
        />
      </AddOrderContent>
    </ReceiptHandlerPopWrap>
  );
};

export default observer(AddOrderHandler);
