import React from 'react';
import { useMutation } from '@tanstack/react-query';
import { fetchOrderRegistration } from 'ApiFarm/addOrder';
import { MenuAddListHandlerAreaWrap } from 'ComponentsFarm/popup/popStyle';
import { Minus, Plus } from 'emotion-icons/fa-solid';
import { observer } from 'mobx-react';
import { orderStore } from 'MobxFarm/store';

interface MenuAddListHandlerAreaProps {
  hideModal: (type: string) => void;
  onEditMenu: (productIdx: number) => void;
  onMenuDeselect: (type: string, productIdx?: number) => void;
}

const MenuAddListHandlerArea = ({
  hideModal,
  onEditMenu,
  onMenuDeselect,
}: MenuAddListHandlerAreaProps) => {
  const { mutate: submitOrder, isLoading } = useMutation(
    fetchOrderRegistration,
    {
      onSuccess: data => {
        console.log('주문 등록 성공:', data);
        orderStore.reset();
        hideModal('pop');
      },
      onError: error => {
        console.error('주문 등록 실패:', error);
      },
    }
  );

  const handleQuantityChange = (
    id: number,
    optionIdx: number | null,
    amount: number
  ) => {
    const menu = orderStore.menus.find(menu => menu.id === id);
    if (menu) {
      if (optionIdx === null) {
        menu.quantity += amount;
        if (menu.quantity <= 0) {
          orderStore.removeMenu(id);
          onMenuDeselect('menu');
        }
      } else {
        const option = menu.selected_options.find(
          option => option.option_idx === optionIdx
        );

        if (option) {
          option.quantity += amount;
          if (option.quantity <= 0) {
            onMenuDeselect('option', optionIdx);
            handleRemoveOption(id, optionIdx);
          }
        }
      }
    }
  };

  const handleRemoveAllMenus = () => {
    orderStore.removeAllMenus();
  };

  const handleRemoveOption = (id: number, optionIdx: number) => {
    const menu = orderStore.menus.find(menu => menu.id === id);

    if (menu) {
      const optionIndex = menu.selected_options.findIndex(
        option => option.option_idx === optionIdx
      );

      if (optionIndex !== -1) {
        menu.selected_options.splice(optionIndex, 1);
      }
    }
  };

  const getTotalQuantity = () => {
    return orderStore.menus.reduce((total, menu) => {
      total += menu.quantity;
      return total;
    }, 0);
  };

  const handleSubmitOrder = async () => {
    const requestBody = {
      item_list: orderStore.menus.map(menu => ({
        product_idx: menu.product_idx,
        quantity: menu.quantity,
        option_list: menu.selected_options.map(option => ({
          product_idx: option.option_idx,
          quantity: option.quantity,
        })),
      })),
    };

    console.log('requestBody', requestBody);

    submitOrder(requestBody);
  };

  return (
    <MenuAddListHandlerAreaWrap>
      <div className="menu_list">
        <h3>메뉴 추가 목록</h3>
        <ul className="list">
          {orderStore.menus.map(menu => (
            <li key={menu.product_idx}>
              <div className="box_menu_item">
                <button
                  type="button"
                  className="txt_product_name"
                  onClick={() => onEditMenu(Number(menu.id))}
                >
                  {menu.product_name}
                </button>
                <span className="box_quanity_handle">
                  <button
                    type="button"
                    className="btn_minus"
                    onClick={() =>
                      handleQuantityChange(Number(menu.id), null, -1)
                    }
                  >
                    <Minus size="16" />
                  </button>
                  <span className="txt_order_quantity">{menu.quantity}</span>
                  <button
                    type="button"
                    className="btn_plus"
                    onClick={() =>
                      handleQuantityChange(Number(menu.id), null, 1)
                    }
                  >
                    <Plus size="16" />
                  </button>
                </span>
              </div>
              <ul className="list_select_options">
                {menu.selected_options.map(option => (
                  <li key={option.option_idx} className="option_item">
                    <span className="txt_option_name">
                      {option.option_name}
                    </span>
                    <span className="box_quanity_handle">
                      <button
                        type="button"
                        className="btn_minus"
                        onClick={() =>
                          handleQuantityChange(
                            Number(menu.id),
                            option.option_idx,
                            -1
                          )
                        }
                      >
                        <Minus size="16" />
                      </button>
                      <span className="txt_order_quantity">
                        {option.quantity}
                      </span>
                      <button
                        type="button"
                        className="btn_plus"
                        onClick={() =>
                          handleQuantityChange(
                            Number(menu.id),
                            option.option_idx,
                            1
                          )
                        }
                      >
                        <Plus size="16" />
                      </button>
                    </span>
                  </li>
                ))}
              </ul>
            </li>
          ))}
        </ul>
        <div className="area_total_order">
          <span className="txt_total">
            <span className="txt">총 주문</span>
            <span className="num">{getTotalQuantity()}</span>
          </span>
          <button type="button" onClick={handleRemoveAllMenus}>
            전체 삭제
          </button>
        </div>
        <button
          type="button"
          className="btn_submit"
          onClick={handleSubmitOrder}
          disabled={orderStore.menus.length === 0 || isLoading}
        >
          {isLoading ? '추가 중...' : '메뉴 추가 하기'}
        </button>
      </div>
    </MenuAddListHandlerAreaWrap>
  );
};

export default observer(MenuAddListHandlerArea);
