import { useEffect, useMemo, useState } from 'react';
import { useInfiniteQuery } from '@tanstack/react-query';
import { fetchHistoryList } from 'ApiFarm/history';
import { IHistoryListRes } from 'ApiFarm/interface/history';
import { AxiosError } from 'axios';
import KdsDatePicker from 'ComponentsFarm/element/KdsDatePicker';
import { HistoryLayerWrap } from 'ComponentsFarm/styles/common';
import dayjs from 'dayjs';

const HistoryLayer = () => {
  const [startDate, setStartDate] = useState(new Date());

  const searchDate = useMemo(
    () => dayjs(startDate).format('YYYY-MM-DD'),
    [startDate]
  );

  const { data, refetch, remove, fetchNextPage, hasNextPage } =
    useInfiniteQuery<IHistoryListRes, AxiosError, IHistoryListRes>(
      ['HistoryListData'],
      async ({ pageParam = 1 }) =>
        fetchHistoryList({ search_ordered_dt: searchDate, page: pageParam }),
      {
        getNextPageParam: lastPage =>
          lastPage.is_next_page ? lastPage.page + 1 : undefined,
      }
    );

  // 스크롤 이벤트 핸들러
  const handleScroll = (e: React.UIEvent<HTMLElement>) => {
    const { scrollTop, clientHeight, scrollHeight } = e.currentTarget;
    if (scrollHeight - scrollTop === clientHeight && hasNextPage) {
      fetchNextPage();
    }
  };

  useEffect(() => {
    remove();
    refetch({ refetchPage: (page, index) => index === 0 });
  }, [startDate]);

  const completedTime = (seconds: number) => {
    const min = (Number(seconds) % 3600) / 60;
    const sec = seconds % 60;
    return `${Math.round(min)}분 ${sec}초`;
  };

  console.log('data123', data);

  return (
    <HistoryLayerWrap className="layer_setting">
      <div className="head">
        <h2>History</h2>
        <KdsDatePicker startDate={startDate} setStartDate={setStartDate} />
      </div>

      <ul className="list_order" onScroll={handleScroll}>
        {data?.pages[0].list.length === 0 ? (
          <li className="nodata">히스토리 내역이 없습니다.</li>
        ) : (
          data?.pages.map(page =>
            page.list.map(el => (
              <li key={el.receipt_number}>
                <div className="orderid">
                  <span className="txt_id_number">NO. {el.receipt_number}</span>
                  <span className="txt_sale_type">
                    {el.sale_type === 0
                      ? '내점'
                      : el.sale_type === 1
                        ? '포장'
                        : '배달'}
                  </span>
                </div>
                <div className="info_time">
                  <div className="time">{el.ordered_at}</div>
                  <div className="completed">
                    {completedTime(el.processing_time)} 경과
                  </div>
                </div>
                <ul className="order_menu">
                  {el.product_list.map(item => (
                    <li key={el.receipt_number + item}>{item}</li>
                  ))}
                </ul>
              </li>
            ))
          )
        )}
      </ul>
    </HistoryLayerWrap>
  );
};

export default HistoryLayer;
