// MenuSelectArea.tsx
import React from 'react';
import { observer } from 'mobx-react';

interface SetOption {
  product_idx: number;
  class_name: string;
  product_name: string;
  is_prep: number;
}

interface MenuSelectAreaProps {
  itemData?: {
    list: Array<{
      product_idx: number;
      product_name: string;
      set_option_list: SetOption[];
    }>;
  };
  selectedCategory: number | null;
  selectedMenu: number | null;
  selectedOptions: number[];
  onMenuSelect: (productIdx: number) => void;
  onOptionSelect: (optionIdx: number) => void;
  onAddToOrder: () => void;
}

const MenuSelectArea = ({
  itemData,
  selectedCategory,
  selectedMenu,
  selectedOptions,
  onMenuSelect,
  onOptionSelect,
  onAddToOrder,
}: MenuSelectAreaProps) => {
  console.log('selectedCategory', selectedCategory);
  return (
    <div
      className={`wrap_select_menu ${
        selectedCategory === 6 || selectedCategory === 7 ? 'full' : ''
      }`}
    >
      <div className="box_select_menu">
        <h4>메뉴 선택</h4>
        <ul className="list_item">
          {itemData?.list.map(item => (
            <li key={item.product_idx}>
              <button
                type="button"
                className={selectedMenu === item.product_idx ? 'on' : ''}
                onClick={() => onMenuSelect(item.product_idx)}
              >
                {item.product_name}
              </button>
            </li>
          ))}
        </ul>
        {(selectedCategory === 6 || selectedCategory === 7) && (
          <button
            type="button"
            className="btn_add_to_order"
            onClick={onAddToOrder}
          >
            {selectedOptions.length === 0
              ? '메뉴만 추가하기'
              : `${selectedOptions.length}개 옵션 추가하기`}
          </button>
        )}
      </div>
      {selectedCategory !== 6 && selectedCategory !== 7 && (
        <div className="box_select_option">
          <h4>옵션 선택</h4>
          {selectedMenu ? (
            <>
              <ul className="list_item list_select_option">
                {itemData?.list
                  .find(item => item.product_idx === selectedMenu)
                  ?.set_option_list.map(option => (
                    <li key={option.product_idx}>
                      <button
                        type="button"
                        className={
                          selectedOptions.includes(option.product_idx)
                            ? 'selected'
                            : ''
                        }
                        onClick={() => onOptionSelect(option.product_idx)}
                      >
                        {option.product_name}
                      </button>
                    </li>
                  ))}
              </ul>
              <button
                type="button"
                className="btn_add_to_order"
                onClick={onAddToOrder}
              >
                {selectedOptions.length === 0
                  ? '메뉴만 추가하기'
                  : `메뉴 +  ${selectedOptions.length} 개 옵션 추가하기`}
              </button>
            </>
          ) : (
            <div className="txt_noOption">
              메뉴를 선택하시면 선택한 메뉴의 옵션이 나타납니다.
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default observer(MenuSelectArea);
